def classify_asset_stage(name):

    if "_O3_30B" in name:
        return "30B"

    if "_O3_30C" in name:
        return "30C"

    if "_O3_30D" in name:
        return "30D"

    if "_O3_30E01" in name:
        return "30E01"

    if "_O3_30E02" in name:
        return "30E02"

    if "_O3_30E03" in name:
        return "30E03"

    if "_O3_30E04" in name:
        return "30E04"

    if "_O3_30G" in name:
        return "30G"

    if "PLANTATION_BOUNDARY" in name:
        return "UPSTREAM_O1"

    if (
        "OUTPUT2" in name
        or
        "LANDSAT_HISTORICAL" in name
        or
        "S2_REGROWTH" in name
    ):
        return "UPSTREAM_O2"

    return "OTHER_RELEVANT"


