def task_snapshot(
    task_id
):

    try:

        status = (
            ee.data.getTaskStatus(
                task_id
            )[0]
        )

        return {
            "task_id":
                task_id,

            "state":
                status.get(
                    "state"
                ),

            "description":
                status.get(
                    "description"
                ),

            "error_message":
                status.get(
                    "error_message"
                )
        }

    except Exception as e:

        return {
            "task_id":
                task_id,

            "state":
                "STATUS_LOOKUP_FAILED",

            "description":
                None,

            "error_message":
                str(e)
        }


