def detect_stage(text):

    text_upper = text.upper()

    patterns = [
        "30A",
        "30B",
        "30C",
        "30D",
        "30E",
        "30F",
        "30G",
        "30H",
        "30I",
        "30J",
    ]

    for stage in patterns:
        if stage in text_upper:
            return stage

    return "UNCLASSIFIED"


cell_rows = []

for idx, cell in enumerate(
    working_nb.cells
):

    source = cell.get(
        "source",
        ""
    )

    first_line = (
        source.strip()
        .splitlines()[0][:150]
        if source.strip()
        else ""
    )

    cell_rows.append({
        "cell_index":
            idx,

        "cell_type":
            cell.cell_type,

        "detected_stage":
            detect_stage(source),

        "first_line":
            first_line,

        "source_length":
            len(source),
    })


