# ============================================================

cells.append(md(
"""
# 30F | Python Feature Screening & Frozen Calibration

30F is the analytical bridge between persistent GEE context
assets and the final integrated product.

The historical experimental notebook is preserved separately
in the package archive.

The final production reconstruction uses only the **frozen**
30F calibration and family weights.

This prevents accidental retuning during routine reruns.
"""
))


cells.append(code(
r'''
CHECKPOINT_30F = (
    PROJECT_ROOT /
    "checkpoints_30F"
)

CALIBRATION_PATH = (
    CHECKPOINT_30F /
    "30F_B18C_AOI01_WALL_TO_WALL_CALIBRATION_V1.csv"
)

FAMILY_WEIGHT_PATH = (
    CHECKPOINT_30F /
    "30F_B18C_FAMILY_WEIGHTS_V1.csv"
)

if not CALIBRATION_PATH.exists():
    raise FileNotFoundError(
        CALIBRATION_PATH
    )

if not FAMILY_WEIGHT_PATH.exists():
    raise FileNotFoundError(
        FAMILY_WEIGHT_PATH
    )


calibration_df = pd.read_csv(
    CALIBRATION_PATH
)

family_weight_df = pd.read_csv(
    FAMILY_WEIGHT_PATH
)


if len(calibration_df) != 8:
    raise ValueError(
        "Expected 8 frozen modifier features."
    )

if len(family_weight_df) != 4:
    raise ValueError(
        "Expected 4 frozen context families."
    )


print(
    "Frozen modifier features :",
    len(calibration_df)
)

print(
    "Frozen families          :",
    len(family_weight_df)
)

display(calibration_df)

display(family_weight_df)
'''
))


# ============================================================
# 15. 30G EXACT FROZEN RECONSTRUCTION
# ============================================================

cells.append(md(
"""
# 30G | Frozen Wall-to-Wall Integrated Product

This section reconstructs the final integration using:

- unchanged B18C calibration;
- frozen feature directions;
- frozen within-family weights;
- frozen family weights;
- F05 modifier amplitude;
- evidence-gated class transitions;
- maximum class change of ±1.

No fitting or tuning occurs here.
"""
))


cells.append(code(
r'''
# ------------------------------------------------------------
# Feature source registry
# ------------------------------------------------------------

feature_source_registry = {

    "LOCAL_RELIEF_300M_M":
        ASSETS["TERRAIN"],

    "SLOPE_DEG":
        ASSETS["TERRAIN"],

    "HAND_M":
        ASSETS["HYDRO"],

    "SILT_PCT_DEEP_100_200CM":
        ASSETS["SOIL"],

    "SOC_GKG_SURFACE_0_30CM":
        ASSETS["SOIL"],

    "WV1500_DEEP_100_200CM":
        ASSETS["SOIL_WATER"],

    "WV10_DEEP_100_200CM":
        ASSETS["SOIL_WATER"],

    "PAW_PROXY_SURFACE_0_30CM":
        ASSETS["SOIL_WATER"],
}


# ------------------------------------------------------------
# Core
# ------------------------------------------------------------

core_img = ee.Image(
    ASSETS["CORE"]
)

core_class = (
    core_img
    .select("CONDITION_CLASS")
    .round()
    .toInt16()
)

core_raw = (
    core_img
    .select("CONDITION_CLASS_RAW")
    .round()
    .toInt16()
)

core_risk = (
    core_img
    .select("RISK_SCORE_0_100")
    .toFloat()
)

valid_mask = (
    core_class.gte(1)
    .And(
        core_class.lte(4)
    )
)


# ------------------------------------------------------------
# Directional feature normalization
#
# P10 -> 0
# P90 -> 1
# negative associations inverted
# [0,1] -> [-1,+1]
# ------------------------------------------------------------

directional_images = {}

for _, row in calibration_df.iterrows():

    feature = row["feature"]

    source = (
        ee.Image(
            feature_source_registry[
                feature
            ]
        )
        .select(feature)
        .toFloat()
        .updateMask(valid_mask)
    )

    p10 = float(
        row["p10"]
    )

    p90 = float(
        row["p90"]
    )

    direction = int(
        row["association_direction"]
    )

    norm01 = (
        source
        .subtract(p10)
        .divide(
            p90 - p10
        )
        .clamp(
            0,
            1
        )
    )

    if direction < 0:

        norm01 = (
            ee.Image.constant(1)
            .subtract(norm01)
        )

    directional_images[
        feature
    ] = (
        norm01
        .multiply(2)
        .subtract(1)
        .rename(
            f"DIR_{feature}"
        )
    )


# ------------------------------------------------------------
# Within-family composites
# ------------------------------------------------------------

family_score_images = {}
family_coverage_images = {}

for family in (
    family_weight_df[
        "family"
    ].tolist()
):

    family_cal = (
        calibration_df[
            calibration_df[
                "family"
            ] == family
        ]
    )

    weighted_sum = (
        ee.Image.constant(0)
        .toFloat()
    )

    available_weight = (
        ee.Image.constant(0)
        .toFloat()
    )

    for _, row in family_cal.iterrows():

        feature = row["feature"]

        weight = float(
            row[
                "within_family_weight"
            ]
        )

        img = directional_images[
            feature
        ]

        valid = (
            img.mask()
            .reduce(
                ee.Reducer.min()
            )
            .gt(0)
        )

        weighted_sum = (
            weighted_sum
            .add(
                img
                .unmask(0)
                .multiply(weight)
            )
        )

        available_weight = (
            available_weight
            .add(
                valid
                .toFloat()
                .multiply(weight)
            )
        )

    family_score = (
        weighted_sum
        .divide(
            available_weight
            .max(1e-6)
        )
        .updateMask(
            available_weight.gte(0.50)
        )
        .clamp(
            -1,
            1
        )
        .rename(
            f"FAMILY_SCORE_{family}"
        )
    )

    family_score_images[
        family
    ] = family_score

    family_coverage_images[
        family
    ] = (
        available_weight
        .rename(
            f"FAMILY_COVERAGE_{family}"
        )
    )


# ------------------------------------------------------------
# Family-balanced overall context modifier
# ------------------------------------------------------------

overall_sum = (
    ee.Image.constant(0)
    .toFloat()
)

overall_weight = (
    ee.Image.constant(0)
    .toFloat()
)

for _, row in family_weight_df.iterrows():

    family = row[
        "family"
    ]

    family_weight = float(
        row[
            "family_weight"
        ]
    )

    img = family_score_images[
        family
    ]

    valid = (
        img.mask()
        .reduce(
            ee.Reducer.min()
        )
        .gt(0)
    )

    overall_sum = (
        overall_sum
        .add(
            img
            .unmask(0)
            .multiply(
                family_weight
            )
        )
    )

    overall_weight = (
        overall_weight
        .add(
            valid
            .toFloat()
            .multiply(
                family_weight
            )
        )
    )


context_modifier = (
    overall_sum
    .divide(
        overall_weight
        .max(1e-6)
    )
    .updateMask(
        overall_weight.gte(0.75)
    )
    .clamp(
        -1,
        1
    )
    .rename(
        "CONTEXT_MODIFIER_SCORE"
    )
)

context_coverage = (
    overall_weight
    .rename(
        "CONTEXT_MODIFIER_COVERAGE"
    )
)


# ------------------------------------------------------------
# F05 integrated score
# ------------------------------------------------------------

FUSION_AMPLITUDE = 5

integrated_score = (
    core_risk
    .add(
        context_modifier
        .unmask(0)
        .multiply(
            FUSION_AMPLITUDE
        )
    )
    .clamp(
        0,
        100
    )
    .rename(
        "INTEGRATED_SCORE_0_100"
    )
)


# ------------------------------------------------------------
# Core evidence
# ------------------------------------------------------------

optical_valid = (
    core_img
    .select(
        "OPTICAL_VALID_PERIOD_COUNT"
    )
)

alert_mask = (
    core_img
    .select(
        "ALERT_MASK"
    )
    .round()
)

max_period_class = (
    core_img
    .select(
        "MAX_PERIOD_CLASS"
    )
)

max_consecutive = (
    core_img
    .select(
        "MAX_CONSECUTIVE_ALERT"
    )
)

optical_alert_total = (
    core_img
    .select(
        "GREENNESS_ALERT_PERIODS"
    )
    .add(
        core_img.select(
            "RED_EDGE_ALERT_PERIODS"
        )
    )
    .add(
        core_img.select(
            "MOISTURE_ALERT_PERIODS"
        )
    )
)

has_optical_support = (
    optical_valid.gt(0)
    .And(
        optical_alert_total.gt(0)
    )
)


# Preserve 30D raw -> final post-processing decisions.

postprocess_lock = (
    core_raw
    .neq(
        core_class
    )
)

unlocked = (
    postprocess_lock
    .Not()
)


# ------------------------------------------------------------
# Frozen AOI01 thresholds
# ------------------------------------------------------------

T12 = 12
T23 = 22
T34 = 32


modifier_available = (
    context_modifier
    .mask()
    .reduce(
        ee.Reducer.min()
    )
    .gt(0)
)

modifier_pos = (
    context_modifier
    .unmask(0)
    .gt(0)
)

modifier_neg = (
    context_modifier
    .unmask(0)
    .lt(0)
)


# ------------------------------------------------------------
# Evidence-gated transitions
# ------------------------------------------------------------

promote_1_2 = (
    core_class.eq(1)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_pos)
    .And(
        integrated_score.gte(T12)
    )
    .And(
        alert_mask.eq(1)
    )
)

promote_2_3 = (
    core_class.eq(2)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_pos)
    .And(
        integrated_score.gte(T23)
    )
    .And(
        has_optical_support
    )
    .And(
        max_period_class.gte(3)
    )
    .And(
        max_consecutive.gte(2)
    )
)

promote_3_4 = (
    core_class.eq(3)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_pos)
    .And(
        integrated_score.gte(T34)
    )
    .And(
        has_optical_support
    )
    .And(
        max_period_class.gte(3)
    )
    .And(
        max_consecutive.gte(3)
    )
)

demote_2_1 = (
    core_class.eq(2)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_neg)
    .And(
        integrated_score.lt(T12)
    )
    .And(
        alert_mask.eq(0)
    )
)

demote_3_2 = (
    core_class.eq(3)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_neg)
    .And(
        integrated_score.lt(T23)
    )
    .And(
        max_consecutive.lte(1)
    )
)

demote_4_3 = (
    core_class.eq(4)
    .And(unlocked)
    .And(modifier_available)
    .And(modifier_neg)
    .And(
        integrated_score.lt(T34)
    )
    .And(
        max_consecutive.lte(2)
    )
)


# ------------------------------------------------------------
# Maximum +/-1 class refinement
# ------------------------------------------------------------

integrated_class = (
    core_class
    .where(
        promote_1_2,
        2
    )
    .where(
        promote_2_3,
        3
    )
    .where(
        promote_3_4,
        4
    )
    .where(
        demote_2_1,
        1
    )
    .where(
        demote_3_2,
        2
    )
    .where(
        demote_4_3,
        3
    )
    .rename(
        "INTEGRATED_CLASS"
    )
    .toInt16()
)

class_delta = (
    integrated_class
    .subtract(
        core_class
    )
    .rename(
        "CLASS_DELTA"
    )
    .toInt16()
)


# ------------------------------------------------------------
# Reconstructed seven-band product
# ------------------------------------------------------------

integrated_img = (
    core_class
    .rename(
        "CORE_CLASS"
    )
    .addBands(
        core_risk.rename(
            "CORE_RISK_SCORE_0_100"
        )
    )
    .addBands(
        context_modifier
    )
    .addBands(
        context_coverage
    )
    .addBands(
        integrated_score
    )
    .addBands(
        integrated_class
    )
    .addBands(
        class_delta
    )
    .updateMask(
        valid_mask
    )
)

print(
    "Reconstructed bands:"
)

print(
    integrated_img
    .bandNames()
    .getInfo()
)
'''
))


# ============================================================
# 16. CANONICAL REPRODUCIBILITY QA
# ============================================================

cells.append(md(
"""
## 30G Canonical Reproducibility Check

The reconstructed frozen product is compared against the
permanent canonical Earth Engine asset.

This is a reproducibility / implementation check.

It is **not field accuracy**.
"""
))


cells.append(code(
r'''
canonical_img = ee.Image(
    ASSETS["CANONICAL"]
)

canonical_proj_info = (
    canonical_img
    .select(
        "INTEGRATED_CLASS"
    )
    .projection()
    .getInfo()
)

canonical_crs = (
    canonical_proj_info[
        "crs"
    ]
)

canonical_transform = (
    canonical_proj_info[
        "transform"
    ]
)


reconstructed_class_aligned = (
    integrated_img
    .select(
        "INTEGRATED_CLASS"
    )
    .reproject(
        crs=canonical_crs,
        crsTransform=canonical_transform
    )
)


class_mismatch = (
    reconstructed_class_aligned
    .neq(
        canonical_img.select(
            "INTEGRATED_CLASS"
        )
    )
    .rename(
        "MISMATCH"
    )
)


mismatch_area_ha = (
    ee.Image.pixelArea()
    .divide(10000)
    .rename(
        "AREA_HA"
    )
    .updateMask(
        class_mismatch
    )
    .reduceRegion(
        reducer=ee.Reducer.sum(),
        geometry=canonical_img.geometry(),
        crs=canonical_crs,
        crsTransform=canonical_transform,
        maxPixels=1e13,
        tileScale=4
    )
    .get(
        "AREA_HA"
    )
    .getInfo()
)

if mismatch_area_ha is None:
    mismatch_area_ha = 0.0


band_names = (
    canonical_img
    .bandNames()
    .getInfo()
)


expected_bands = [
    "CORE_CLASS",
    "CORE_RISK_SCORE_0_100",
    "CONTEXT_MODIFIER_SCORE",
    "CONTEXT_MODIFIER_COVERAGE",
    "INTEGRATED_SCORE_0_100",
    "INTEGRATED_CLASS",
    "CLASS_DELTA",
]


checks = {

    "seven_canonical_bands":
        band_names == expected_bands,

    "reconstructed_class_mismatch_zero":
        float(
            mismatch_area_ha
        ) == 0.0,

    "frozen_fusion_amplitude":
        FUSION_AMPLITUDE == 5,

    "frozen_thresholds":
        (
            T12 == 12
            and T23 == 22
            and T34 == 32
        ),
}


print(
    "Canonical class mismatch area:",
    f"{float(mismatch_area_ha):.6f} ha"
)

print()

for name, result in checks.items():

    print(
        f"{name:40s}:",
        "PASS"
        if result
        else "FAIL"
    )


if not all(
    checks.values()
):
    raise RuntimeError(
        "Canonical reproducibility check failed."
    )

print(
    "\n30G canonical reproducibility : PASS"
)
'''
))


